<?php
declare(strict_types=1);
require __DIR__.'/lib/core.php';
use function Norda\{body,config,csrf,db,fail,json,now,privateDir,published,query,rate,record,role,sameOrigin,saveRecord,seed,session,setupKey,text,upload,user,uuid,can,audit,clean};
try {
    header('X-Robots-Tag: noindex, nofollow');header('X-Content-Type-Options: nosniff');session();$action=$_GET['action']??'status';$method=$_SERVER['REQUEST_METHOD'];
    $gets=['status','list','record','overview','users','revisions','backup','files','download','media-list'];if(!in_array($action,$gets,true)&&$method!=='POST')fail('Bu əməliyyat POST tələb edir.',405);
    if($action==='status'){$c=config();$u=null;if($c&&isset($_SESSION['uid'])){try{$u=user();}catch(Norda\Problem){}}if(!$c)setupKey();json(['installed'=>(bool)$c,'csrf'=>$_SESSION['csrf'],'user'=>$u,'drivers'=>!$c?PDO::getAvailableDrivers():[],'phpCompatible'=>PHP_VERSION_ID>=80100]);}
    if($action==='install'){csrf();rate('install',8,3600);Norda\install(body());json(['installed'=>true]);}
    if(!config())fail('Panel əvvəlcə cPanel-də quraşdırılmalıdır.',503);
    if($action==='login'){csrf();rate('login',10,900);$d=body();$u=query('SELECT * FROM users WHERE email=?',[strtolower(trim((string)($d['email']??'')))])->fetch();if(!$u||$u['disabled']||!password_verify((string)($d['password']??''),$u['password_hash']))fail('E-poçt və ya şifrə düzgün deyil.',401);session_regenerate_id(true);$_SESSION['uid']=$u['id'];$_SESSION['last']=time();$_SESSION['csrf']=bin2hex(random_bytes(32));audit($u['email'],'login','session');unset($u['password_hash']);json(['user'=>$u,'csrf'=>$_SESSION['csrf']]);}
    if($action==='logout'){csrf();$_SESSION=[];session_destroy();json(['ok'=>true]);}
    if($action==='rfq'){
      csrf();$d=json_decode($_POST['payload']??'{}',true);
      if(!is_array($d)||!empty($d['website'])||($d['consent']??false)!==true)fail('Sorğu məlumatını və razılığı yoxlayın.');
      foreach(['company','person','contact','details']as$f)if(trim((string)($d[$f]??''))==='')fail('Məcburi sahələri doldurun.');
      $contact=(string)$d['contact'];if(!filter_var($contact,FILTER_VALIDATE_EMAIL)&&!preg_match('/^\+?[0-9 ()-]{7,30}$/D',$contact))fail('Əlaqə məlumatı düzgün deyil.');
      $submission=(string)($d['submission_id']??'');if(strlen($submission)>99)fail('Sorğu identifikatoru düzgün deyil.');
      if($submission!==''&&isset($_SESSION['submissions'][$submission]))json($_SESSION['submissions'][$submission]);
      rate('rfq',10,3600);if(count($_FILES)>3)fail('Maksimum 3 fayl əlavə edin.');
      $id=uuid();saveRecord($id,'request',array_merge($d,['status'=>'new','notes'=>'']),0,['email'=>'website']);$errors=[];
      foreach(array_slice($_FILES,0,3)as$f){try{upload($f,$id);}catch(Norda\Problem$e){$errors[]=$e->getMessage();}}
      $result=['id'=>$id,'reference'=>'NTS-'.strtoupper(substr($id,0,8)),'attachmentErrors'=>$errors];
      if($submission!==''){$_SESSION['submissions'][$submission]=$result;if(count($_SESSION['submissions'])>30)array_shift($_SESSION['submissions']);}
      json($result,201);
    }
    if($action==='overview'){$u=user();$kinds=$u['role']==='editor'?Norda\CONTENT:($u['role']==='sales'?['request','quote','customer']:array_merge(Norda\CONTENT,['request','quote','customer','supplier']));$counts=[];foreach($kinds as$k)$counts[$k]=(int)query('SELECT COUNT(*) FROM records WHERE kind=? AND archived=0',[$k])->fetchColumn();$recent=$u['role']==='editor'?[]:query("SELECT id,data,updated_at FROM records WHERE kind='request' AND archived=0 ORDER BY updated_at DESC LIMIT 8")->fetchAll();foreach($recent as&$r)$r['data']=json_decode($r['data'],true);$logs=$u['role']==='owner'?query('SELECT actor,action,entity,created_at FROM audit ORDER BY created_at DESC LIMIT 15')->fetchAll():[];json(['counts'=>$counts,'requests'=>$recent,'audit'=>$logs]);}
    if($action==='list'){$kind=(string)($_GET['kind']??'category');can($kind);$rows=query('SELECT * FROM records WHERE kind=? AND archived=? ORDER BY updated_at DESC LIMIT 1000',[$kind,($_GET['archived']??'')==='1'?1:0])->fetchAll();foreach($rows as&$r){$r['data']=json_decode($r['data'],true);$r['published']=$r['published']?json_decode($r['published'],true):null;$r['revision']=(int)$r['revision'];}json(['records'=>$rows]);}
    if($action==='record'){$r=record((string)($_GET['id']??''));can($r['kind']);json(['record'=>$r]);}
    if($action==='save'){csrf();$d=body();$kind=(string)($d['kind']??'');$u=can($kind);$id=isset($d['id'])&&$d['id']!==''?(string)$d['id']:uuid();if(!preg_match('/^[a-zA-Z0-9-]{2,80}$/D',$id))fail('Qeyd nömrəsi düzgün deyil.');json(['record'=>saveRecord($id,$kind,$d['data']??[],(int)($d['revision']??0),$u)]);}
    if(in_array($action,['publish','archive','unarchive'],true)){csrf();$d=body();$r=record((string)($d['id']??''));$u=can($r['kind'],true);if((int)($d['revision']??0)!==$r['revision'])fail('Qeyd yenilənib. Səhifəni yeniləyin.',409);if($action==='publish'){Norda\checkPublicPaths($r);if(in_array($r['kind'],['category','product','brand','article'],true)){if(empty($r['data']['image'])||!is_file(dirname(__DIR__).'/'.$r['data']['image']))fail('Yayımlamadan əvvəl mövcud şəkil və ya loqo seçin.');if($r['kind']==='category')foreach(published('category')as$other)if($other['id']!==$r['id']&&$other['image']===$r['data']['image'])fail('Bu şəkil başqa kateqoriyada istifadə olunur. Ayrı şəkil seçin.');}if(!in_array($r['kind'],Norda\CONTENT,true))fail('Bu qeyd yayımlanmır.');if(in_array($r['kind'],['category','product','article'],true)){foreach(published($r['kind'])as$other)if($other['id']!==$r['id']&&$other['slug']===$r['data']['slug'])fail('Bu ünvan artıq istifadə olunur.',409);}query('UPDATE records SET published=data,revision=revision+1,updated_at=?,updated_by=? WHERE id=?',[now(),$u['email'],$r['id']]);}elseif($action==='unarchive'){$check=$r;$check['data']=$r['published']??$r['data'];Norda\checkPublicPaths($check);query('UPDATE records SET archived=0,revision=revision+1,updated_at=?,updated_by=? WHERE id=?',[now(),$u['email'],$r['id']]);}else{if($r['kind']==='company')fail('Şirkət ayarları arxivləşdirilə bilməz.');query('UPDATE records SET archived=1,revision=revision+1,updated_at=?,updated_by=? WHERE id=?',[now(),$u['email'],$r['id']]);}audit($u['email'],$action,$r['kind'].':'.$r['id']);json(['record'=>record($r['id'])]);}
    if($action==='revisions'){$r=record((string)($_GET['id']??''));can($r['kind']);$rows=query('SELECT id,record_id,created_by,created_at FROM revisions WHERE record_id=? ORDER BY created_at DESC LIMIT 50',[$r['id']])->fetchAll();json(['revisions'=>$rows]);}
    if($action==='restore'){csrf();$d=body();$old=query('SELECT * FROM revisions WHERE id=?',[$d['revision_id']??''])->fetch();if(!$old)fail('Versiya tapılmadı.',404);$r=record($old['record_id']);$u=can($r['kind']);json(['record'=>saveRecord($r['id'],$r['kind'],json_decode($old['data'],true),$r['revision'],$u)]);}
    if($action==='media-list'){role(['owner','editor']);$items=seed()['media']??[];foreach(query("SELECT original_name,stored_name FROM files WHERE record_id='media' ORDER BY created_at DESC LIMIT 500")as$f)$items[]=['path'=>'media/'.$f['stored_name'],'name'=>$f['original_name']];json(['media'=>$items]);}
    if($action==='media'){csrf();$u=role(['owner','editor']);$f=$_FILES['file']??null;if(!$f)fail('Fayl seçin.');$a=upload($f,'media',true);audit($u['email'],'upload','media:'.$a['id']);json($a,201);}
    if($action==='files'){$r=record((string)($_GET['id']??''));can($r['kind']);json(['files'=>query('SELECT id,original_name,mime,size_bytes FROM files WHERE record_id=?',[$r['id']])->fetchAll()]);}
    if($action==='download'){$f=query('SELECT * FROM files WHERE id=?',[$_GET['id']??''])->fetch();if(!$f)fail('Fayl tapılmadı.',404);$r=record($f['record_id']);can($r['kind']);$p=privateDir().'/attachments/'.basename($f['stored_name']);if(!is_file($p))fail('Fayl tapılmadı.',404);header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="attachment.'.pathinfo($f['stored_name'],PATHINFO_EXTENSION).'"');header('Cache-Control: private, no-store');readfile($p);exit;}
    if($action==='users'){role(['owner']);json(['users'=>query('SELECT id,email,name,role,disabled FROM users ORDER BY email')->fetchAll()]);}
    if($action==='save-user'){csrf();$owner=role(['owner']);$d=body();$id=$d['id']??uuid();$email=strtolower(text($d['email']??'',180));$name=text($d['name']??'',120);$r=$d['role']??'editor';$disabled=!empty($d['disabled'])?1:0;if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($r,['owner','editor','sales'],true))fail('İstifadəçi məlumatı düzgün deyil.');$existing=query('SELECT * FROM users WHERE id=?',[$id])->fetch();if($existing&&$existing['role']==='owner'&&($r!=='owner'||$disabled)&&(int)query("SELECT COUNT(*) FROM users WHERE role='owner' AND disabled=0")->fetchColumn()<=1)fail('Son sahib hesabı deaktiv edilə bilməz.');$p=(string)($d['password']??'');if(!$existing&&strlen($p)<12)fail('Ən azı 12 simvolluq şifrə tələb olunur.');if($p!==''&&(strlen($p)<12||strlen($p)>200))fail('Şifrə 12–200 simvol olmalıdır.');if($existing){query('UPDATE users SET email=?,name=?,role=?,disabled=? WHERE id=?',[$email,$name,$r,$disabled,$id]);if($p!=='')query('UPDATE users SET password_hash=? WHERE id=?',[password_hash($p,PASSWORD_DEFAULT),$id]);}else query('INSERT INTO users(id,email,name,password_hash,role,disabled,created_at) VALUES(?,?,?,?,?,?,?)',[$id,$email,$name,password_hash($p,PASSWORD_DEFAULT),$r,$disabled,now()]);audit($owner['email'],'user-update',$id);json(['ok'=>true]);}
    if($action==='backup'){$u=role(['owner']);$rows=query("SELECT id,kind,data,published,revision,archived FROM records WHERE kind IN ('category','product','brand','article','page','company')")->fetchAll();foreach($rows as&$r){$r['data']=json_decode($r['data'],true);$r['published']=$r['published']?json_decode($r['published'],true):null;}audit($u['email'],'backup','content');header('Content-Disposition: attachment; filename="norda-content-'.gmdate('Ymd-His').'.json"');json(['format'=>'norda-content-v1','created_at'=>now(),'records'=>$rows]);}
    if($action==='restore-backup'){csrf();$u=role(['owner']);$d=body(12000000);if(($d['format']??'')!=='norda-content-v1'||count($d['records']??[])>1000)fail('Ehtiyat nüsxəsi düzgün deyil.');$validated=[];foreach($d['records']as$r){if(!in_array($r['kind'],Norda\CONTENT,true))fail('Nüsxədə qəbul edilməyən bölmə var.');$validated[]=['id'=>text($r['id'],80),'kind'=>$r['kind'],'data'=>clean($r['kind'],$r['data'])];}db()->beginTransaction();try{foreach($validated as$r){$old=query('SELECT revision FROM records WHERE id=?',[$r['id']])->fetchColumn();saveRecord($r['id'],$r['kind'],$r['data'],(int)$old,$u);}db()->commit();}catch(Throwable$e){if(db()->inTransaction())db()->rollBack();throw$e;}audit($u['email'],'restore-backup','content');json(['restoredDrafts'=>count($validated)]);}
    fail('Əməliyyat tapılmadı.',404);
}catch(Norda\Problem$e){json(['error'=>$e->getMessage()],$e->status);}catch(Throwable$e){error_log('Norda admin failure: '.get_class($e));json(['error'=>'Server əməliyyatı tamamlamadı. Hostinq jurnalını yoxlayın.'],500);}
